/// Parse a (possibly negative) decimal string into an Integer.
fn parse_int(s: &str) -> Integer {
    let (neg, digits) = if let Some(rest) = s.strip_prefix('-') { (true, rest) } else { (false, s) };
    let mut acc = Integer::zero();
    let ten = Integer::from(10);
    for ch in digits.bytes() {
        acc = acc * ten.clone() + Integer::from((ch - b'0') as i64);
    }
    if neg { -acc } else { acc }
}

#[test]
fn discriminant_matches_pari_poldisc() {
    for (i, c) in POLYS.iter().enumerate() {
        let f: Vec<Integer> = c.iter().map(|&x| Integer::from(x)).collect();
        let got = discriminant(&f);
        let expect = parse_int(DISCS[i]);
        assert_eq!(got, expect, "poldisc mismatch at poly {}", i);
    }
}
